/* Existing counter integration, protected against restricted storage. No form data is sent. */
(window.cheersTrackPage=()=>{if(window.__cheersPreview)return;const host=location.hostname;if(!['cheersexperiences.com','www.cheersexperiences.com'].includes(host)&&!host.endsWith('.chatgpt.site'))return;const page=location.pathname.endsWith('/eventos.html')?'/eventos.html':'/';const key='cheers-view:'+page;try{if(sessionStorage.getItem(key)===location.href+':'+performance.timeOrigin)return;sessionStorage.setItem(key,location.href+':'+performance.timeOrigin);}catch{}fetch('https://cheers-visit-counter.cccerjn.chatgpt.site/api/visit',{method:'POST',mode:'cors',credentials:'omit',keepalive:true,headers:{'Content-Type':'application/json'},body:JSON.stringify({page})}).catch(()=>{});})();
